"""Compare the copied input boundary and decode the first divergent D1 checkpoint."""

import hashlib
import json
from pathlib import Path
import sys

from rich.console import Console
import torch

from bio_inspired_nanochat.checkpoint_manager import require_complete_checkpoint
from scripts.e2e.scaleup_checkpoint_recovery import compare_state


def digest(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def artifacts(step):
    tag = f"{step:06d}"
    return [f"model_{tag}.pt", *(
        f"{kind}_{tag}_rank{rank}.pt" for kind in ("optim", "train") for rank in (0, 1)
    )]


def stats(a, b, name):
    result = {"tensors": 0, "non_bitwise_tensors": 0, "max_abs_delta": 0.0, "mismatches": []}
    compare_state(a, b, name, exact=True, stats=result)
    return result


left, right, output = map(Path, sys.argv[1:])
for directory in (left, right):
    for step in (2, 3):
        require_complete_checkpoint(str(directory), step)

input_sha256 = {name: [digest(directory / name) for directory in (left, right)] for name in artifacts(2)}
assert all(first == second for first, second in input_sha256.values())

comparisons = {}
for name in artifacts(3):
    first, second = (torch.load(directory / name, weights_only=True, map_location="cpu", mmap=True)
                     for directory in (left, right))
    if name.startswith("train_"):
        assert first.keys() == second.keys()
        comparisons[name] = {field: stats(first[field], second[field], field) for field in first}
    else:
        comparisons[name] = {"whole_file": stats(first, second, name)}
    del first, second

with output.open("x") as stream:
    json.dump({"input_sha256": input_sha256, "step": 3, "comparisons": comparisons},
              stream, indent=2, sort_keys=True)
    stream.write("\n")

summary = {
    name: {field: {"checked_tensors": item["tensors"], "different": len(item["mismatches"]),
                   "first_differences": item["mismatches"][:3]}
           for field, item in fields.items()}
    for name, fields in comparisons.items()
}
Console().print_json(data=summary)

