"""Check the actual detached scan backward on frozen operands and fresh execution orders."""

import hashlib
import json
import math
import os
from pathlib import Path
import subprocess
import sys
from types import SimpleNamespace

from rich.console import Console


def worker(mode, order, dest):
    import torch
    from bio_inspired_nanochat.synaptic import _DetachedScanReleaseGrad

    rng = torch.Generator(device="cpu").manual_seed(237)
    device = torch.device("cuda", 0)
    torch.cuda.set_device(device)

    def fixture(shape, cap, sampled, strided):
        extent = (*shape[:2], shape[2] + 2, shape[3]) if strided else shape

        def floats():
            return torch.rand(extent, generator=rng, device="cpu").to(device)[:, :, :shape[2]]

        drive, incoming, ca, buf, primed, clamp, rrp, energy, noise, ema = (
            floats() for _ in range(10)
        )
        valid = floats() > 0.1
        mask = (floats() < sampled) & valid
        return (
            2.0 * drive - 1.0, incoming * 1e-5, valid, ca, buf, primed, clamp,
            rrp * 5, energy, mask, noise, ema + 0.1,
            SimpleNamespace(
                tau_c=-1.0 / math.log(0.97), alpha_ca=0.45, alpha_buf_on=0.08,
                alpha_buf_off=0.02, syt_fast_kd=0.11, syt_slow_kd=0.41,
                doc2_gain=1.2, complexin_bias=0.05, stochastic_count_cap=cap,
                q_beta=2.0, qmax=1.0,
            ),
        )

    cases = {
        "zero_count": fixture((2, 3, 12, 4), 0, 1.0, False),
        "deterministic": fixture((2, 3, 9, 4), 8, 0.0, True),
        "half_geometry": fixture((1, 2, 17, 8), 3, 0.35, True),
        "d1_geometry": fixture((8, 5, 64, 32), 8, 0.12, False),
    }

    def fingerprint(x):
        bytes_view = x.detach().contiguous().view(torch.uint8).cpu().numpy()
        return hashlib.sha256(bytes_view.tobytes()).hexdigest()

    def backward(args):
        drive, incoming, valid, *edges, config = args
        drive = drive.detach().requires_grad_(True)
        release = _DetachedScanReleaseGrad.apply(
            drive, torch.zeros_like(drive), valid, config, *edges,
        )
        return torch.autograd.grad(release, drive, incoming)[0]

    cpu_rows = []
    if order == "cpu_first":
        cpu_args = tuple(x.cpu() if isinstance(x, torch.Tensor) else x for x in cases["deterministic"])
        cpu_rows = [fingerprint(backward(cpu_args)) for _ in range(4)]

    sequence = list(cases)
    if order == "permuted":
        sequence = ["half_geometry", "d1_geometry", "deterministic", "zero_count"]
    first = {name: fingerprint(backward(cases[name])) for name in sequence}
    for _ in range(2):
        for name in sequence:
            backward(cases[name])
    warmed = {name: fingerprint(backward(cases[name])) for name in sequence}
    repeated = {name: fingerprint(backward(cases[name])) for name in sequence}

    graphs = {}
    if mode == "candidate":
        stream = torch.cuda.Stream(device=device)
        stream.wait_stream(torch.cuda.current_stream(device))
        with torch.cuda.stream(stream):
            for name in sequence:
                backward(cases[name])
        stream.synchronize()
        for name in sequence:
            graph = torch.cuda.CUDAGraph()
            try:
                with torch.cuda.graph(graph, stream=stream):
                    result = backward(cases[name])
                graph.replay()
                torch.cuda.synchronize(device)
                graphs[name] = {"exact": fingerprint(result) == warmed[name]}
            except RuntimeError as error:
                graphs[name] = {"exact": False, "error": str(error)}
                break

    with dest.open("x") as stream:
        json.dump({
            "order": order, "first": first, "warmed": warmed, "repeated": repeated, "graphs": graphs,
            "inputs": {name: [fingerprint(x) if isinstance(x, torch.Tensor) else vars(x)
                             for x in args] for name, args in cases.items()},
            "cpu": cpu_rows,
        }, stream, sort_keys=True)


def main(candidate, incumbent, out):
    out.mkdir()
    arms = (
        ("incumbent", "cuda_first", incumbent), ("incumbent", "cpu_first", incumbent),
        ("candidate", "cuda_first", candidate), ("candidate", "cpu_first", candidate),
        ("candidate", "permuted", candidate),
    )
    results = {}
    for mode, order, checkout in arms:
        arm = f"{mode}_{order}"
        Console().print("Frozen adjoint inputs", arm)
        target = out / f"{arm}.json"
        env = {**os.environ, "PYTHONPATH": str(checkout)}
        subprocess.run([sys.executable, __file__, "worker", mode, order, str(target)], cwd=checkout,
                       env=env, check=True)
        results[arm] = json.loads(target.read_bytes())

    reference = results["incumbent_cuda_first"]
    assert all(row["inputs"] == reference["inputs"] for row in results.values())
    def differences(actual, expected):
        return [name for name, expected_hash in expected.items() if actual[name] != expected_hash]

    comparable = {
        arm: {
            "first_vs_warmed_cuda_incumbent": differences(row["first"], reference["warmed"]),
            "warmed_vs_warmed_cuda_incumbent": differences(row["warmed"], reference["warmed"]),
            "repeated_vs_own_warmed": differences(row["repeated"], row["warmed"]),
            "graph_mismatches": [name for name, result in row["graphs"].items() if not result["exact"]],
            "graph_count": len(row["graphs"]),
        } for arm, row in results.items()
    }
    cpu_equal = results["incumbent_cpu_first"]["cpu"] == results["candidate_cpu_first"]["cpu"]
    with (out / "comparison.json").open("x") as stream:
        json.dump({"comparisons": comparable, "cpu_equal": cpu_equal, "results": results}, stream,
                  indent=2, sort_keys=True)
        stream.write("\n")
    Console().print_json(data={"comparisons": comparable, "cpu_equal": cpu_equal})
    assert comparable["incumbent_cpu_first"]["warmed_vs_warmed_cuda_incumbent"], "negative control"
    assert cpu_equal
    for arm, report in comparable.items():
        if arm.startswith("candidate"):
            assert not report["first_vs_warmed_cuda_incumbent"]
            assert not report["warmed_vs_warmed_cuda_incumbent"]
            assert not report["repeated_vs_own_warmed"]
            assert not report["graph_mismatches"] and report["graph_count"] == 4


if sys.argv[1] == "worker":
    worker(sys.argv[2], sys.argv[3], Path(sys.argv[4]))
else:
    main(*(Path(arg) for arg in sys.argv[1:]))
